{"code": "// Does switching from all-or-nothing scoring to fractional test-pass-rate restore power?
// Model: 30 tasks, task difficulty p_i ~ U(0.35,0.85). Each task has M=10 sub-tests.
// Treatment shifts each sub-test prob by +delta (absolute).
function power(useFractional: boolean, delta: number, M = 10, n = 30, trials = 1500): number {
  let sig = 0;
  for (let t = 0; t < trials; t++) {
    let diffs: number[] = [];
    for (let i = 0; i < n; i++) {
      const p = 0.35 + Math.random() * 0.5;
      // base run
      let kBase = 0, kTrt = 0;
      for (let m = 0; m < M; m++) {
        if (Math.random() < p) kBase++;
        if (Math.random() < Math.min(0.99, p + delta)) kTrt++;
      }
      const sBase = useFractional ? kBase / M : (kBase === M ? 1 : 0);
      const sTrt  = useFractional ? kTrt  / M : (kTrt  === M ? 1 : 0);
      diffs.push(sTrt - sBase);
    }
    const mean = diffs.reduce((a, b) => a + b, 0) / n;
    const varr = diffs.reduce((a, b) => a + (b - mean) ** 2, 0) / (n - 1);
    const se = Math.sqrt(varr / n);
    if (se > 0 && mean / se > 1.96) sig++;
  }
  return sig / trials;
}

console.log("=== 功效对比：0/1 判分 vs 通过率判分（n=30, 每题 10 个子测试）===");
console.log("效应量   0/1判分   通过率判分   提升");
for (const delta of [0.02, 0.04, 0.06, 0.10]) {
  const b = power(false, delta);
  const f = power(true, delta);
  console.log(`${(delta*100).toFixed(0).padStart(3)}pp    ${(b*100).toFixed(0).padStart(5)}%   ${(f*100).toFixed(0).padStart(8)}%    ${b>0 ? (f/b).toFixed(1)+"x" : "—"}`);
}
", "description": "Test whether fractional scoring restores statistical power"}

